#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll INF=4000000000000000000LL;
struct Node{ll sum=0,left=INF,right=INF,pair=INF;bool ok=false;};
struct Seg{int n;vector<ll>&a,&b;vector<Node>tr;Seg(int n,vector<ll>&a,vector<ll>&b):n(n),a(a),b(b),tr(4*n){build(1,1,n);}Node join(Node x,Node y,ll w){if(!x.ok)return y;if(!y.ok)return x;Node z;z.ok=1;z.sum=x.sum+w+y.sum;z.left=min(x.left,x.sum+w+y.left);z.right=min(y.right,y.sum+w+x.right);z.pair=min({x.pair+w+y.sum,x.sum+w+y.pair,x.left+y.right});return z;}void build(int p,int l,int r){if(l==r){tr[p]={0,b[l],b[l],INF,true};return;}int m=(l+r)/2;build(p*2,l,m);build(p*2+1,m+1,r);tr[p]=join(tr[p*2],tr[p*2+1],a[m]);}void upd(int p,int l,int r,int x){if(l==r){tr[p]={0,b[l],b[l],INF,true};return;}int m=(l+r)/2;if(x<=m)upd(p*2,l,m,x);else upd(p*2+1,m+1,r,x);tr[p]=join(tr[p*2],tr[p*2+1],a[m]);}void upd(int x){upd(1,1,n,x);}Node get(int p,int l,int r,int ql,int qr){if(ql<=l&&r<=qr)return tr[p];int m=(l+r)/2;if(qr<=m)return get(p*2,l,m,ql,qr);if(ql>m)return get(p*2+1,m+1,r,ql,qr);return join(get(p*2,l,m,ql,qr),get(p*2+1,m+1,r,ql,qr),a[m]);}Node get(int l,int r){return get(1,1,n,l,r);}Node cyc(int l,int r){if(l<=r)return get(l,r);return join(get(l,n),get(1,r),a[n]);}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,q;cin>>n>>q;vector<ll>a(n+1),b(n+1);for(int i=1;i<=n;i++)cin>>a[i];for(int i=1;i<=n;i++)cin>>b[i];Seg st(n,a,b);while(q--){int ty,x;ll y;cin>>ty>>x>>y;if(ty==2){a[x]=y;st.upd(x);}else if(ty==3){b[x]=y;st.upd(x);}else{int s=x,t=(int)y;if(t==n+1){int pre=s==1?n:s-1,suc=s==n?1:s+1;cout<<min(st.cyc(s,pre).left,st.cyc(suc,s).right)<<'\n';continue;}Node A=st.get(s,t),B=st.cyc(t,s);Node LA=st.get(s,t-1),RA=st.get(s+1,t);int pre=s==1?n:s-1,suc=t==n?1:t+1;Node LB=st.cyc(t,pre),RB=st.cyc(suc,s);cout<<min({A.sum,B.sum,A.pair,B.pair,LA.left+LB.left,RA.right+RB.right})<<'\n';}}}}
